1	"use client";
2	import { useEffect, useRef, useState } from "react";
3	import dynamic from "next/dynamic";
4	import { useSearchParams } from "next/navigation";
5	import { useRouter, usePathname } from "@i18n/routing";
6	// import useOnScreen from "components/hooks/useOnScreen";
7	import { useAuth } from "@components/hooks/useAuth";
8	import { useEventAnalytics } from "./hooks/useEventAnalytics";
9	
10	import type { EventClientProps } from "types/props";
11	import EventNotifications from "./components/EventNotifications";
12	// import { useEventModals } from "./hooks/useEventModals";
13	// import EventModals from "./components/EventModals";
14	import { MegaphoneIcon as SpeakerphoneIcon } from "@heroicons/react/24/outline";
15	import AdArticle from "components/ui/adArticle";
16	import SectionHeading from "@components/ui/common/SectionHeading";
17	import { useTranslations } from "next-intl";
18	import { sendGoogleEvent } from "@utils/analytics";
19	
20	// computeTemporalStatus now imported from utils/event-status for reuse & testability
21	
22	// Lazy load the post-publish promote upsell modal — every event detail page
23	// view goes through this component, but the modal is only ever relevant
24	// right after the owner published (see the `promote=1` marker below), so it
25	// shouldn't ship in every page view's bundle.
26	const PromoteUpsellModal = dynamic(
27	  () => import("./components/PromoteUpsellModal"),
28	  { ssr: false },
29	);
30	
31	export default function EventClient({
32	  event,
33	}: EventClientProps) {
34	  const t = useTranslations("Components.EventPage");
35	  const router = useRouter();
36	  const pathname = usePathname();
37	  const { user } = useAuth();
38	  // const editModalRef = useRef<HTMLDivElement>(null);
39	
40	  // const isEditModalVisible = useOnScreen(
41	  //   editModalRef as React.RefObject<Element>,
42	  //   {
43	  //     freezeOnceVisible: true,
44	  //   }
45	  // );
46	
47	  const searchParams = useSearchParams() ?? new URLSearchParams();
48	  const newEvent = searchParams.get("newEvent");
49	  const edit_suggested = searchParams.get("edit_suggested") === "true";
50	  const [showThankYouBanner, setShowThankYouBanner] = useState(edit_suggested);
51	
52	  // Post-publish promote upsell: publica/page.tsx redirects here with
53	  // ?promote=1 right after a successful publish (see design doc's "Modal"
54	  // section — the modal lives on the event's own detail page, not on the
55	  // publish form). Same one-time-marker convention as newEvent/edit_suggested
56	  // above, not a new mechanism.
57	  //
58	  // Gated on ownership: the marker is just a URL query param, so anyone could
59	  // append ?promote=1 to any event's URL. Without this check, a non-owner
60	  // visitor would see the upsell and its CTA would lead to the owner-only
61	  // /promote page, which 404s for them. isOwner is undefined (not false)
62	  // while the auth session is still resolving, so the modal only ever shows
63	  // once ownership is positively confirmed — never as a flash-then-hide.
64	  const isOwner = user?.id === event.ownerId;
65	  const initialShowPromoteUpsell = searchParams.get("promote") === "1";
66	  const [dismissed, setDismissed] = useState(false);
67	  // Derived, not stored state: isOwner/initialShowPromoteUpsell already fully
68	  // determine visibility each render, so there's nothing to sync from an
69	  // effect here (that was the earlier react-hooks/set-state-in-effect error).
70	  const showPromoteUpsell = initialShowPromoteUpsell && isOwner && !dismissed;
71	
72	  const hasFiredShownEvent = useRef(false);
73	  useEffect(() => {
74	    if (showPromoteUpsell && !hasFiredShownEvent.current) {
75	      hasFiredShownEvent.current = true;
76	      sendGoogleEvent("promote_modal_shown", {
77	        event_slug: event.slug ?? "",
78	        source: "event_detail",
79	      });
80	    }
81	  }, [showPromoteUpsell, event.slug]);
82	
83	  const handlePromoteUpsellOpenChange = (open: boolean) => {
84	    if (open) return;
85	    setDismissed(true);
86	    // Strip only the one-time marker so a refresh or shared link doesn't
87	    // re-trigger the modal — preserve any other existing query params
88	    // (e.g. edit_suggested) rather than dropping the whole query string.
89	    const remainingParams = new URLSearchParams(searchParams.toString());
90	    remainingParams.delete("promote");
91	    const query = remainingParams.toString();
92	    router.replace(query ? `${pathname}?${query}` : pathname, {
93	      scroll: false,
